            if (readResponse.AuthorOption.IsSet)
                writer.WriteString("author", readResponse.Author);

            if (readResponse.PublishedOption.IsSet)
                writer.WriteString("published", readResponse.Published);

            if (readResponse.SiteOption.IsSet)
                writer.WriteString("site", readResponse.Site);

            if (readResponse.LangOption.IsSet)
                writer.WriteString("lang", readResponse.Lang);

            if (readResponse.MarkdownOption.IsSet)
                writer.WriteString("markdown", readResponse.Markdown);

            if (readResponse.TextOption.IsSet)
                writer.WriteString("text", readResponse.Text);

            if (readResponse.FetchedOption.IsSet)
                writer.WriteString("fetched", readResponse.FetchedOption.Value!.Value.ToString(FetchedFormat));

            if (readResponse.CachedOption.IsSet)
                writer.WriteBoolean("cached", readResponse.CachedOption.Value!.Value);

            if (readResponse.RestrictedOption.IsSet)
                if (readResponse.RestrictedOption.Value != null)
                {
                    writer.WritePropertyName("restricted");
                    JsonSerializer.Serialize(writer, readResponse.Restricted, jsonSerializerOptions);
                }
                else
                    writer.WriteNull("restricted");
        }
    }
}
